/bin/bash -lc "rtk proxy python3 - <<'PY'
import json,pathlib,collections
p=pathlib.Path('docs/evidence/technical-implementation-planning-precision-v3/focused/q4-shared-drift')
d=json.loads((p/'result.json').read_text())
def meta(x,path='',depth=0):
 if isinstance(x,dict):
  for k,v in x.items():
   q=path+'/'+k
   if isinstance(v,(dict,list)):
    print(q,type(v).__name__,len(v))
    if depth<2 and k not in ('items','content'):meta(v,q,depth+1)
   else:print(q,str(v)[:250])
 elif isinstance(x,list):
  for n,v in enumerate(x):
   if depth<2:meta(v,path+'/'+str(n),depth+1)
meta(d)
print('STAGE ITEM METADATA')
s=json.loads((p/'planning-audit.json').read_text())
for n,w in enumerate(s['items']):
 i=w['item'];print(n,i['id'],i['type'],i.get('tool',''),len(json.dumps(i)))
ls=[json.loads(l) for l in (p/'planning-audit.jsonl').read_text().splitlines()]
print('TRACE METHODS',dict(collections.Counter(l['message'].get('method',l['direction']) for l in ls)))
print('COMPLETED TRACE ITEMS')
for n,l in enumerate(ls):
 m=l['message'];i=m.get('params',{}).get('item',{})
 if m.get('method')=='item/completed': print(n,i.get('id'),i.get('type'))
PY"

